const SOL_CLASS = {
  'Point of Sale':'pos', 'Virtual Solution':'virtual', 'Gateway':'gateway',
  'API Solution':'api', 'Internal':'internal'
};
const state = { q:'', cat:null, sol:'', sort:'rank' };
const $ = id => document.getElementById('at-' + id);
const grid = $('grid'), sheet = $('sheet'), overlay = $('overlay');
let lastFocus = null;
let merchantName = '';
let ae = {name:'', phone:'', email:''};
try{ ae = Object.assign(ae, JSON.parse(localStorage.getItem('wpi_ae')||'{}')); }catch(e){}
function saveAE(){ try{ localStorage.setItem('wpi_ae', JSON.stringify(ae)); }catch(e){} }

let syncCats;
/* ---------- category pills ---------- */
(function(){
  const counts = {};
  DATA.forEach(d=>counts[d.category]=(counts[d.category]||0)+1);
  const cats = Object.keys(counts).sort((a,b)=>counts[b]-counts[a] || a.localeCompare(b));
  const host = $('cats');
  const mk = (label,val,n)=>{
    const b = document.createElement('button');
    b.className='cat'; b.setAttribute('aria-pressed', String(state.cat===val));
    b.innerHTML = label + (n!=null?'<span class="n">'+n+'</span>':'');
    b.addEventListener('click',()=>{ state.cat = (state.cat===val?null:val); syncCats(); render(); });
    b.dataset.val = val===null?'':val;
    return b;
  };
  host.appendChild(mk('All',null,DATA.length));
  cats.forEach(c=>host.appendChild(mk(c,c,counts[c])));
  syncCats = function(){
    host.querySelectorAll('.cat').forEach(b=>{
      const v = b.dataset.val===''?null:b.dataset.val;
      b.setAttribute('aria-pressed', String(state.cat===v));
    });
  };
})();

/* ---------- filtering ---------- */
function filtered(){
  const q = state.q.trim().toLowerCase();
  let out = DATA.filter(d=>{
    if(state.cat && d.category!==state.cat) return false;
    if(state.sol && d.solution_type!==state.sol) return false;
    if(q){
      const c = d.contact||{};
      const hay = (d.name+' '+d.category+' '+(d.niche||'')+' '+(d.blurb||'')+' '+(d.company||'')+' '+(d.site_note||'')+' '+(c.name||'')+' '+(c.phone||'')).toLowerCase();
      if(!hay.includes(q)) return false;
    }
    return true;
  });
  if(state.sort==='rank') out.sort((a,b)=>b.rank-a.rank || a.name.localeCompare(b.name));
  else if(state.sort==='name') out.sort((a,b)=>a.name.localeCompare(b.name));
  else out.sort((a,b)=>a.category.localeCompare(b.category) || b.rank-a.rank);
  return out;
}

/* ---------- render ---------- */
function esc(s){ return String(s==null?'':s).replace(/[&<>"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
const PHONE_ICO = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M3 2.5 h2.6 l1.2 3 -1.7 1.3 a9.5 9.5 0 0 0 4.1 4.1 l1.3 -1.7 3 1.2 v2.6 a1.4 1.4 0 0 1 -1.5 1.4 A12.6 12.6 0 0 1 1.6 4 1.4 1.4 0 0 1 3 2.5 z"/></svg>';
const SHARE_ICO = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M8 1.8 V10"/><path d="M5.2 4.4 L8 1.6 L10.8 4.4"/><path d="M3.5 7.5 H3 a1.5 1.5 0 0 0 -1.5 1.5 v4 A1.5 1.5 0 0 0 3 14.5 h10 a1.5 1.5 0 0 0 1.5 -1.5 v-4 A1.5 1.5 0 0 0 13 7.5 h-.5"/></svg>';

const cardCache = new Map();
function render(){
  const items = filtered();
  $('count').innerHTML = 'Showing <b>'+items.length+'</b> of '+DATA.length+' brands';
  const frag = document.createDocumentFragment();
  items.forEach(d=>{
    let el = cardCache.get(d);
    if(el){ frag.appendChild(el); return; }
    el = document.createElement('button');
    el.className='item'; el.type='button';
    const cls = d.rank>=8?'hi':(d.rank<=4?'lo':'');
    const sol = SOL_CLASS[d.solution_type]||'internal';
    el.innerHTML =
      '<div class="item-top"><div><h3>'+esc(d.name)+'</h3>'+
      '<span class="cat-label">'+esc(d.category)+'</span></div>'+
      '<div class="score '+cls+'"><b>'+d.rank+'</b><i>/10</i></div></div>'+
      '<p class="blurb">'+esc(d.blurb||d.niche||'')+'</p>'+
      '<div class="item-foot"><span class="fee">'+esc(d.fee||'—')+'</span>'+
      '<span class="foot-right"><span class="share-btn" role="button" tabindex="0" data-share title="Text or email flyer" aria-label="Text or email flyer for '+esc(d.name)+'">'+SHARE_ICO+'</span>'+(d.contact&&d.contact.phone?'<span class="has-contact" title="Direct line on file">'+PHONE_ICO+'</span>':'')+
      '<span class="pill '+sol+'">'+esc(d.solution_type||'—')+'</span></span></div>';
    el.addEventListener('click',()=>openSheet(d));
    const sb = el.querySelector('[data-share]');
    sb.addEventListener('click',(ev)=>{ ev.stopPropagation(); shareFlyer(d); });
    sb.addEventListener('keydown',(ev)=>{ if(ev.key==='Enter'||ev.key===' '){ ev.preventDefault(); ev.stopPropagation(); shareFlyer(d); } });
    cardCache.set(d, el);
    frag.appendChild(el);
  });
  grid.replaceChildren(frag);
  if(!items.length){
    grid.innerHTML = '<div class="empty"><b>Nothing matches</b>Try clearing a filter or shortening the search.</div>';
  }
}

