const CHECK = '<svg viewBox="0 0 20 20" fill="none"><circle cx="10" cy="10" r="8.6" stroke="var(--green)" stroke-width="1.7"/><path d="M6.4 10.4 L9 13 L13.8 7.6" stroke="var(--green)" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const EXT = '<svg viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2.5 H2.5 V11.5 H11.5 V8"/><path d="M8.5 2 H12 V5.5"/><path d="M12 2 L6.8 7.2"/></svg>';

function contactBox(d){
  const c = d.contact;
  let rows = '';
  if(d.company) rows += '<div class="crow"><span class="k">Company</span><span class="v">'+esc(d.company)+'</span></div>';
  if(c){
    if(c.name)  rows += '<div class="crow"><span class="k">Contact</span><span class="v">'+esc(c.name)+'</span></div>';
    if(c.phone) rows += '<div class="crow"><span class="k">Phone</span><span class="v"><a href="tel:+1'+esc(c.phone.replace(/\D/g,''))+'">'+esc(c.phone)+'</a></span></div>';
    if(c.phone2)rows += '<div class="crow"><span class="k">Alt. phone</span><span class="v"><a href="tel:+1'+esc(c.phone2.replace(/\D/g,''))+'">'+esc(c.phone2)+'</a></span></div>';
    if(c.email) rows += '<div class="crow"><span class="k">Email</span><span class="v"><a href="mailto:'+esc(c.email)+'">'+esc(c.email)+'</a></span></div>';
  }
  if(d.website){
    let host = d.website.replace(/^https?:\/\//,'').replace(/\/.*$/,'');
    rows += '<div class="crow"><span class="k">Website</span><span class="v"><a href="'+esc(d.website)+'" target="_blank" rel="noopener noreferrer">'+esc(host)+'</a></span></div>';
  }
  if(!rows){
    rows = '<p class="contact-note">No direct line on file for this brand yet &mdash; start with the vendor&rsquo;s site or your Wholesale Payments integration desk.</p>';
  }
  return '<div class="group-box"><p class="lbl">Who to call</p><div class="contact-rows">'+rows+'</div></div>';
}

function convBox(d){
  let rows = '';
  rows += '<div class="crow"><span class="k">EMV terminals</span><span class="v">'+(d.emv?'Yes':'No')+'</span></div>';
  rows += '<div class="crow"><span class="k">Gift cards</span><span class="v">'+(d.gift?'Yes':'No')+'</span></div>';
  if(d.cash_discount) rows += '<div class="crow"><span class="k">Cash discount</span><span class="v">'+esc(d.cash_discount)+'</span></div>';
  if(d.hardware) rows += '<div class="crow"><span class="k">Hardware</span><span class="v">'+esc(d.hardware)+'</span></div>';
  if(d.conversion_costs) rows += '<div class="crow"><span class="k">Conversion cost</span><span class="v">'+esc(d.conversion_costs)+'</span></div>';
  const note = d.site_note ? '<p class="contact-note" style="margin-top:12px; padding-top:12px; border-top:1px solid var(--hairline)">'+esc(d.site_note)+'</p>' : '';
  return '<div class="group-box"><p class="lbl">Conversion &amp; compatibility</p><div class="contact-rows">'+rows+'</div>'+note+'</div>';
}

function openSheet(d){
  lastFocus = document.activeElement;
  fromAnalysis();
  const meter = Array.from({length:10},(_,i)=>'<i class="'+(i<d.rank?'on':'')+'"></i>').join('');
  const sol = SOL_CLASS[d.solution_type]||'internal';
  const rows = [];
  rows.push('<div class="crow"><span class="k">Category</span><span class="v">'+esc(d.category)+'</span></div>');
  rows.push('<div class="crow"><span class="k">Solution type</span><span class="v"><span class="pill '+sol+'">'+esc(d.solution_type||'—')+'</span></span></div>');
  if(d.niche) rows.push('<div class="crow"><span class="k">Niche</span><span class="v">'+esc(d.niche)+'</span></div>');
  if(d.last_modified) rows.push('<div class="crow"><span class="k">Listing updated</span><span class="v">'+esc(d.last_modified)+'</span></div>');

  sheet.innerHTML =
    '<div class="sheet-head">'+
      '<button class="sheet-close" id="at-closeBtn" aria-label="Close">&#10005;</button>'+
      '<span class="cat-label">'+esc(d.category)+'</span>'+
      '<h2 id="at-sheetTitle">'+esc(d.name)+'</h2>'+
      (d.blurb?'<p class="blurb">'+esc(d.blurb)+'</p>':'')+
      '<div class="sheet-tags"><span class="pill '+sol+'">'+esc(d.solution_type||'—')+'</span></div>'+
    '</div>'+
    '<div class="sheet-body">'+
      '<div class="group-box"><p class="lbl">Ranking</p>'+
        '<div class="meter-row"><span class="meter-num">'+d.rank+'<small>/10</small></span><div class="meter" role="img" aria-label="Rank '+d.rank+' out of 10">'+meter+'</div></div></div>'+
      contactBox(d)+
      convBox(d)+
      '<div class="group-box"><p class="lbl">SaaS fees</p>'+
        '<p class="fee-big">'+esc(d.fee||'Unknown')+'</p>'+
        (d.fee_note?'<p class="fee-note">'+esc(d.fee_note)+'</p>':'')+
        (d.fee_source?'<p class="fee-src">Verified via '+esc(d.fee_source)+'</p>':'')+'</div>'+
      '<div class="group-box"><p class="lbl">Why merchants pick it</p>'+
        '<ul class="benefits">'+(d.benefits||[]).map(b=>'<li>'+CHECK+'<span>'+esc(b)+'</span></li>').join('')+'</ul></div>'+
      '<div class="group-box"><p class="lbl">Directory details</p><div class="contact-rows">'+rows.join('')+'</div></div>'+
    '</div>'+
    '<div class="sheet-cta"><input class="merchant-field" id="at-merchantInput" type="text" maxlength="60" placeholder="Merchant name (prints on the flyer)" value="'+esc(merchantName)+'" aria-label="Merchant name to print on the flyer">'+
    '<input class="merchant-field" id="at-aeName" type="text" maxlength="50" placeholder="Account executive name" value="'+esc(ae.name)+'" aria-label="Account executive name">'+
    '<div class="ae-row"><input class="merchant-field" id="at-aePhone" type="tel" maxlength="25" placeholder="AE phone" value="'+esc(ae.phone)+'" aria-label="Account executive phone">'+
    '<input class="merchant-field" id="at-aeEmail" type="email" maxlength="60" placeholder="AE email" value="'+esc(ae.email)+'" aria-label="Account executive email"></div>'+
    '<button class="visit alt" id="at-flyerBtn" type="button">Text or email this flyer '+SHARE_ICO+'</button>'+
    (d.website?'<a class="visit" href="'+esc(d.website)+'" target="_blank" rel="noopener noreferrer">Visit '+esc(d.name)+' '+EXT+'</a>':'')+'</div>';
  $('merchantInput').addEventListener('input', (e)=>{ merchantName = e.target.value; });
  $('aeName').addEventListener('input', (e)=>{ ae.name = e.target.value; saveAE(); });
  $('aePhone').addEventListener('input', (e)=>{ ae.phone = e.target.value; saveAE(); });
  $('aeEmail').addEventListener('input', (e)=>{ ae.email = e.target.value; saveAE(); });
  $('flyerBtn').addEventListener('click', ()=>shareFlyer(d));
  overlay.classList.add('open');
  sheet.classList.add('open');
  document.body.style.overflow='hidden';
  $('closeBtn').addEventListener('click', closeSheet);
  $('closeBtn').focus();
}
function closeSheet(){
  overlay.classList.remove('open');
  sheet.classList.remove('open');
  document.body.style.overflow='';
  if(lastFocus) lastFocus.focus();
}
overlay.addEventListener('click', closeSheet);
document.addEventListener('keydown', e=>{
  if(e.key==='Escape' && sheet.classList.contains('open')) closeSheet();
  if(e.key==='/' && atlasShown() && !/^(INPUT|TEXTAREA|SELECT)$/.test((document.activeElement||{}).tagName||'') && document.activeElement !== $('q')){ e.preventDefault(); $('q').focus(); }
});


/* ---------- flyer PDF generator (dependency-free) ---------- */
const PDF_NAVY='0.051 0.106 0.298', PDF_BLUE='0.035 0.482 0.910', PDF_GREEN='0.184 0.714 0.373',
      PDF_LGREEN='0.659 0.855 0.573', PDF_GREY='0.42 0.43 0.46', PDF_INK='0.114 0.114 0.122',
      PDF_LINE='0.90 0.905 0.92', PDF_WHITE='1 1 1', PDF_PALE='0.961 0.973 0.988';

const WPI_LOGO_B64='';
const WPI_LOGO_W=1150, WPI_LOGO_H=342;
let WPI_LOGO_BIN=null;

function pdfText(s){
  const MAP={'\u2019':'\\222','\u2018':'\\221','\u201C':'\\223','\u201D':'\\224','\u2013':'\\226','\u2014':'\\227','\u2022':'\\225','\u00A2':'\\242','\u00E9':'\\351','\u00AE':'\\256','\u2122':'\\231'};
  let out='';
  for(const ch of String(s)){
    if(ch==='\\') out+='\\\\';
    else if(ch==='(') out+='\\(';
    else if(ch===')') out+='\\)';
    else if(MAP[ch]!==undefined) out+=MAP[ch];
    else if(ch.charCodeAt(0)<=126) out+=ch;
  }
  return out;
}
function estW(s,size,bold){
  let w=0;
  for(const ch of String(s)){
    let f=0.545;
    if('iljt.,:;\'!|f'.includes(ch)) f=0.30;
    else if('mwMW'.includes(ch)) f=0.90;
    else if(ch===' ') f=0.278;
    else if(ch>='A'&&ch<='Z') f=0.70;
    w+=f*size;
  }
  return bold? w*1.06 : w;
}
function pdfWrap(s,size,maxW,bold){
  const words=String(s).split(/\s+/), lines=[]; let cur='';
  for(const w of words){
    const test=cur?cur+' '+w:w;
    if(estW(test,size,bold)>maxW && cur){ lines.push(cur); cur=w; }
    else cur=test;
  }
  if(cur) lines.push(cur);
  return lines;
}
function rr(x,y,w,h,r){
  const k=0.5523*r;
  return `${x+r} ${y} m ${x+w-r} ${y} l ${x+w-r+k} ${y} ${x+w} ${y+r-k} ${x+w} ${y+r} c `+
         `${x+w} ${y+h-r} l ${x+w} ${y+h-r+k} ${x+w-r+k} ${y+h} ${x+w-r} ${y+h} c `+
         `${x+r} ${y+h} l ${x+r-k} ${y+h} ${x} ${y+h-r+k} ${x} ${y+h-r} c `+
         `${x} ${y+r} l ${x} ${y+r-k} ${x+r-k} ${y} ${x+r} ${y} c h `;
}
function txt(font,size,color,x,y,s,charSpace){
  return `BT /${font} ${size} Tf ${color} rg ${charSpace?charSpace+' Tc ':'0 Tc '}${x} ${y} Td (${pdfText(s)}) Tj ET\n`;
}
function buildFlyerPDF(d){
  const W=612,H=792,M=46,CW=W-2*M;
  let o='';
  o+='1 1 1 rg 0 0 612 792 re f\n';
  o+='q 0 784 612 8 re W n /ShBrand sh Q\n';
  // header — exact Wholesale Payments logo image
  if(!WPI_LOGO_BIN) WPI_LOGO_BIN=atob(WPI_LOGO_B64);
  const lgH=46, lgW=lgH*WPI_LOGO_W/WPI_LOGO_H;
  o+=`q ${lgW} 0 0 ${lgH} ${M} ${H-94} cm /Im1 Do Q\n`;
  const merch=(merchantName||'').trim();
  if(merch){
    o+=txt('F2',7,PDF_GREY,W-M-estW('PREPARED FOR',7,true)-8,H-58,'PREPARED FOR',1.3);
    let mSize=13;
    while(estW(merch,mSize,true)>236 && mSize>9) mSize-=1;
    o+=txt('F2',mSize,PDF_NAVY,W-M-estW(merch,mSize,true),H-74,merch);
  }
  o+=PDF_LINE+' RG 1 w '+`${M} ${H-104} m ${W-M} ${H-104} l S\n`;
  // brand name + rank
  let nameSize=30;
  while(estW(d.name,nameSize,true)>CW-150 && nameSize>16) nameSize-=2;
  o+=txt('F2',nameSize,PDF_NAVY,M,H-146,d.name);
  o+=txt('F1',11,PDF_GREY,M,H-165,d.category+(d.solution_type?'  \u2022  '+d.solution_type:''));
  const rankStr=String(d.rank);
  o+=txt('F2',34,PDF_NAVY,W-M-118,H-152,rankStr);
  o+=txt('F1',13,PDF_GREY,W-M-118+estW(rankStr,34,true)+3,H-152,'/10  rank');
  for(let i=0;i<10;i++){
    o+=(i<d.rank?PDF_GREEN:PDF_LINE)+' rg '+rr(W-M-120+i*12.2,H-170,9.6,5,2.2)+'f\n';
  }
  // blurb
  let y=H-200;
  for(const ln of pdfWrap(d.blurb||d.niche||'',12,CW,false).slice(0,3)){
    o+=txt('F1',12,PDF_INK,M,y,ln); y-=17;
  }
  // benefits
  y-=16;
  o+=txt('F2',10,PDF_GREY,M,y,'WHY MERCHANTS PICK IT',1.3); y-=24;
  for(const b of (d.benefits||[]).slice(0,3)){
    o+=PDF_GREEN+' RG 1.6 w '+`${M+4} ${y+3} m ${M+8} ${y-1} l ${M+15} ${y+8} l S\n`;
    o+=txt('F1',13,PDF_INK,M+26,y,b);
    y-=25;
  }
  // dual pricing panel — light reflective brand gradient
  const pTop=y-14, pBot=150, pH=pTop-pBot;
  o+='q '+rr(M,pBot,CW,pH,16)+'W n /ShPanel sh Q\n';
  let py=pTop-42;
  o+=txt('F2',26,PDF_GREEN,M+28,py,'NO MORE'); py-=27;
  o+=txt('F2',20,PDF_NAVY,M+28,py,'Credit Card Processing Fees'); py-=30;
  const bullets=['0% Credit Card Processing Cost','$0 Transaction Fee','Free State-of-the-Art Equipment','No Hidden Fees','$45 Flat Fee Per Month'];
  for(const b of bullets){
    o+=PDF_GREEN+' rg '+rr(M+30,py+2.5,5,5,2.5)+'f\n';
    o+=txt('F2',12.5,PDF_NAVY,M+44,py,b);
    py-=21;
  }
  // guarantee card (right side of panel)
  const gX=M+CW*0.52, gW=CW*0.44, gH=130, gY=pTop-74-gH;
  o+=PDF_WHITE+' rg '+rr(gX,gY,gW,gH,12)+'f\n';
  o+='0.729 0.847 0.945 RG 0.9 w '+rr(gX,gY,gW,gH,12)+'S\n';
  let gy=gY+gH-26;
  o+=txt('F2',15,PDF_NAVY,gX+16,gy,'$500 GUARANTEE'); gy-=18;
  for(const ln of pdfWrap("If we can't beat your current rates, we will give your business a $500 check for taking a few minutes to allow us to do a comparison.",9.5,gW-32,false)){
    o+=txt('F1',9.5,PDF_GREY,gX+16,gy,ln); gy-=13;
  }
  // dual pricing explainer under bullets
  let ey=py-4;
  o+=txt('F2',11,'0.106 0.518 0.910',M+28,ey,'DUAL PRICING'); ey-=15;
  for(const ln of pdfWrap('Empower your customers to choose: pay the cash price, or cover the card price. You keep 100% of every sale.',9.5,CW*0.48,false)){
    o+=txt('F1',9.5,PDF_GREY,M+28,ey,ln); ey-=13;
  }
  // account manager lines
  o+=PDF_INK+' rg\n';
  o+=txt('F2',10,PDF_INK,M,92,'Account Manager:');
  o+='0.6 0.62 0.66 RG 0.8 w '+`${M+92} 90 m ${W-M} 90 l S\n`;
  o+=txt('F2',10,PDF_INK,M,66,'Phone:');
  o+=`${M+40} 64 m ${M+240} 64 l S\n`;
  o+=txt('F2',10,PDF_INK,M+266,66,'Email:');
  o+=`${M+304} 64 m ${W-M} 64 l S\n`;
  const aeN=(ae.name||'').trim(), aeP=(ae.phone||'').trim(), aeE=(ae.email||'').trim();
  if(aeN) o+=txt('F1',11,PDF_NAVY,M+100,93.5,aeN);
  if(aeP) o+=txt('F1',11,PDF_NAVY,M+48,67.5,aeP);
  if(aeE){
    let eSize=11;
    while(estW(aeE,eSize,false)>W-M-(M+312) && eSize>8) eSize-=0.5;
    o+=txt('F1',eSize,PDF_NAVY,M+312,67.5,aeE);
  }

  // assemble objects
  const objs=[];
  objs.push('<< /Type /Catalog /Pages 2 0 R >>');
  objs.push('<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
  objs.push('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R /F2 6 0 R >> /Shading << /ShBrand 7 0 R /ShPanel 8 0 R >> /XObject << /Im1 9 0 R >> >> /Contents 4 0 R >>');
  objs.push('<< /Length '+o.length+' >>\nstream\n'+o+'endstream');
  objs.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
  objs.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  objs.push('<< /ShadingType 2 /ColorSpace /DeviceRGB /Coords [0 788 612 788] /Function << /FunctionType 2 /Domain [0 1] /C0 [0.106 0.518 0.910] /C1 [0.239 0.745 0.424] /N 1 >> /Extend [true true] >>');
  objs.push('<< /ShadingType 2 /ColorSpace /DeviceRGB /Coords [46 490 566 150] /Function << /FunctionType 2 /Domain [0 1] /C0 [0.902 0.941 0.988] /C1 [0.910 0.965 0.925] /N 1 >> /Extend [true true] >>');
  objs.push('<< /Type /XObject /Subtype /Image /Width '+WPI_LOGO_W+' /Height '+WPI_LOGO_H+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+WPI_LOGO_BIN.length+' >>\nstream\n'+WPI_LOGO_BIN+'\nendstream');
  let pdf='%PDF-1.4\n%\u00E2\u00E3\u00CF\u00D3\n';
  const offsets=[];
  objs.forEach((body,i)=>{ offsets.push(pdf.length); pdf+=(i+1)+' 0 obj\n'+body+'\nendobj\n'; });
  const xref=pdf.length;
  pdf+='xref\n0 '+(objs.length+1)+'\n0000000000 65535 f \n';
  offsets.forEach(off=>{ pdf+=String(off).padStart(10,'0')+' 00000 n \n'; });
  pdf+='trailer\n<< /Size '+(objs.length+1)+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';
  const bytes=new Uint8Array(pdf.length);
  for(let i=0;i<pdf.length;i++) bytes[i]=pdf.charCodeAt(i)&0xFF;
  return bytes;
}

let toastTimer=null;
function showToast(msg){
  let el=$('toast');
  if(!el){
    el=document.createElement('div'); el.id='at-toast';
    el.style.cssText='position:fixed;left:50%;bottom:28px;transform:translateX(-50%);z-index:80;background:var(--ink);color:var(--page);padding:11px 18px;border-radius:12px;font-size:13px;max-width:88vw;text-align:center;box-shadow:0 10px 30px rgba(0,0,0,.25);opacity:0;transition:opacity .25s ease';
    document.body.appendChild(el);
  }
  el.textContent=msg;
  requestAnimationFrame(()=>{ el.style.opacity='1'; });
  clearTimeout(toastTimer);
  toastTimer=setTimeout(()=>{ el.style.opacity='0'; },5000);
}

async function shareFlyer(d){
  try{
    const bytes=buildFlyerPDF(d);
    const fname=d.name.replace(/[^\w\- ]+/g,'').trim().replace(/\s+/g,'-')+'-wholesale-payments.pdf';
    const file=new File([bytes],fname,{type:'application/pdf'});
    if(navigator.canShare && navigator.canShare({files:[file]})){
      await navigator.share({files:[file], title:d.name+' \u2014 Wholesale Payments', text:'Integration flyer for '+d.name});
      return;
    }
    if(window.claude){
      showToast('Flyer sharing works on the live site \u2014 open wpiintegrations.com to text, email, or download it.');
      return;
    }
    const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));
    const a=document.createElement('a');
    a.href=url; a.download=fname;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),4000);
  }catch(err){
    if(err && err.name==='AbortError') return;
    console.error('Flyer share failed:', err);
  }
}

